package com.example

import com.example.ExamQuestionHelper.QSpec

object HealthLiveExamTeamSportsBank1 {
    private const val T = "කණ්ඩායම් ක්‍රීඩා, ජලජ ක්‍රීඩා හා තරගාවලි සංවිධානය"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("ශ්‍රී ලංකාවේ නිල ජාතික ක්‍රීඩාව ලෙස 1991 වසරේදී ප්‍රකාශයට පත් කරන ලද කණ්ඩායම් ක්‍රීඩාව කුමක්ද?", "වොලිබෝල් ක්‍රීඩාව (Volleyball)", "ක්‍රිකට් ක්‍රීඩාව", "එල්ලේ ක්‍රීඩාව", "දැල්පන්දු ක්‍රීඩාව", "ශ්‍රී ලංකාවේ ගම්බද හා නගරබද අතිශය ජනප්‍රිය වොලිබෝල් ක්‍රීඩාව මෙරට ජාතික ක්‍රීඩාව වේ."),
        q("සම්මත වොලිබෝල් ක්‍රීඩා පිටියක නිල දිග සහ පළල පිළිවෙළින් මීටර් කීයද?", "දිග මීටර් 18ක් සහ පළල මීටර් 9ක් (18m × 9m)", "දිග මීටර් 20ක් සහ පළල මීටර් 10ක්", "දිග මීටර් 15ක් සහ පළල මීටර් 8ක්", "දිග මීටර් 25ක් සහ පළල මීටර් 12ක්", "වොලිබෝල් පිටිය මීටර් 9x9 ප්‍රමාණයේ සමාන කොටු දෙකකට මැද දැලෙන් වෙන් කර ඇත."),
        q("වොලිබෝල් පිටියේ මැද ඉරේ (Center Line) සිට ප්‍රහාරක කලාපය වෙන් කරමින් දෙපසට ඇඳ ඇති රේඛාව කුමක්ද?", "ප්‍රහාරක රේඛාව හෙවත් මීටර් 3 රේඛාව (Attack Line)", "සේවා රේඛාව", "මායිම් රේඛාව", "නිදහස් රේඛාව", "ප්‍රහාරක රේඛාව මැද ඉරේ සිට මීටර් 3ක් ඈතින් පිහිටන අතර පසුපස කලාපයේ ක්‍රීඩකයන්ට ඉන් ඉදිරියට පැමිණ පහර ගැසීම සීමා කෙරේ."),
        q("ජ්‍යෙෂ්ඨ පිරිමි වොලිබෝල් තරග සඳහා දැලෙහි (Net) සම්මත උස ප්‍රමාණය මීටර් කීයද?", "මීටර් 2.43කි", "මීටර් 2.24කි", "මීටර් 2.50කි", "මීටර් 2.10කි", "පිරිමි නිල වොලිබෝල් දැලක මධ්‍යයේ උස මීටර් 2.43ක් (2.43m) වේ."),
        q("ජ්‍යෙෂ්ඨ කාන්තා වොලිබෝල් තරග සඳහා දැලෙහි සම්මත නිල උස ප්‍රමාණය කොපමණද?", "මීටර් 2.24කි", "මීටර් 2.43කි", "මීටර් 2.00කි", "මීටර් 2.15කි", "කාන්තා නිල වොලිබෝල් දැලෙහි උස මීටර් 2.24ක් (2.24m) වේ."),
        q("වොලිබෝල් දැල දෙපස සිරස්ව සවිකර ඇති ඇන්ටනාවක (Antenna) සම්පූර්ණ දිග සහ දැලෙන් ඉහළට නෙරා ඇති කොටසේ උස කොපමණද?", "සම්පූර්ණ දිග මීටර් 1.80ක් සහ දැලෙන් ඉහළට නෙරා ඇති උස සෙන්ටිමීටර 80ක්", "සම්පූර්ණ දිග මීටර් 2.00ක් සහ ඉහළට මීටර් 1ක්", "සම්පූර්ණ දිග මීටර් 1.50ක් සහ ඉහළට සෙන්ටිමීටර 50ක්", "සම්පූර්ණ දිග මීටර් 1.00ක්", "ඇන්ටනාවෙන් මීටර් 1ක් දැලට සවි වන අතර සෙන්ටිමීටර 80ක් දැලෙන් ඉහළට නෙරා සිටී."),
        q("වොලිබෝල් තරගයකදී පන්දුව විරුද්ධ පිලට යැවිය යුත්තේ කුමන සීමාවක් තුළින්ද?", "ඇන්ටනා දෙක අතරින් සහ ඒවායේ මනඃකල්පිත ඉහළ දිගුව තුළින් පමණි", "ඇන්ටනාවට පිටතින්", "ඇන්ටනාවේ වදින ලෙස පමණි", "දැලට යටින්", "පන්දුව ඇන්ටනාවේ ස්පර්ශ වීම හෝ ඇන්ටනාවට පිටතින් විරුද්ධ පිලට යාම නීති විරෝධී (Out) වේ."),
        q("වොලිබෝල් ක්‍රීඩා පිටියක එකවර එක් කණ්ඩායමකින් පිටියේ ක්‍රීඩා කරන නිල ක්‍රීඩකයන් සංඛ්‍යාව කීයද?", "ක්‍රීඩකයන් 6කි (සහ ආදේශක 6ක් සමග මුළු 12ක්)", "ක්‍රීඩකයන් 5කි", "ක්‍රීඩකයන් 7කි", "ක්‍රීඩකයන් 11කි", "එක් පිලකින් ක්‍රීඩකයන් 6 දෙනෙකු පිටියේ ස්ථාන 6ක ස්ථානගත වේ."),
        q("වොලිබෝල් ක්‍රීඩාවේදී පන්දු පිරිනැමීමේ (Service) අයිතිය තම පිලට ලැබුණු විට ක්‍රීඩකයන් ස්ථාන මාරු විය යුතු නිවැරදි දිශානතිය කුමක්ද?", "දක්ෂිණාවර්තව හෙවත් ඔරලෝසු කටුව කැරකෙන දිශාවට (Clockwise)", "වාමාවර්තව", "කැමති ඕනෑම පැත්තකට", "ඉදිරියට හා පසුපසට පමණි", "ක්‍රීඩකයන් 1 සිට 6, 6 සිට 5, 5 සිට 4, 4 සිට 3, 3 සිට 2, 2 සිට 1 දක්වා දක්ෂිණාවර්තව භ්‍රමණය (Rotate) වේ."),
        q("වොලිබෝල් පිටියේ පන්දු පිරිනැමීම (Serve) සිදුකරනු ලබන්නේ කුමන ස්ථානයේ (Position) සිටින ක්‍රීඩකයා විසින්ද?", "ස්ථාන අංක 1 (Position 1 — දකුණු පසුපස ක්‍රීඩකයා)", "ස්ථාන අංක 6", "ස්ථාන අංක 4", "ස්ථාන අංක 3", "පසුපස දකුණු කෙළවරේ ස්ථාන 1 ක්‍රීඩකයා සේවා සීමාවේ සිට පන්දුව පිරිනමයි."),
        q("වොලිබෝල් තරගයකදී එක් කණ්ඩායමකට පන්දුව විරුද්ධ පිලට යැවීමට පෙර තම පිල තුළ උපරිම වශයෙන් ලබාගත හැකි පහරවල් ගණන කීයද?", "පහරවල් 3ක් පමණි (ආවරණය හැර)", "පහරවල් 4ක්", "පහරවල් 2ක්", "අසීමිත පහරවල් ගණනක්", "ආවරණ පහරක් (Block) පහරක් ලෙස නොගණින අතර ඉන්පසු තවත් පහර 3ක් තම පිලට ගත හැක."),
        q("වොලිබෝල් ක්‍රීඩාවේදී එකම ක්‍රීඩකයෙකුට අඛණ්ඩව පිට පිට දෙවරක් පන්දුවට පහර දිය හැකිද?", "නැත, එය 'ද්විත්ව පහර' (Double Contact) නීති විරෝධී වරදකි", "ඔව්, ඕනෑම වාර ගණනක් ගැසිය හැක", "පළමු වටයේදී පමණක් හැක", "පසුපස ක්‍රීඩකයාට පමණක් හැක", "එක් ක්‍රීඩකයෙකු එක දිගට දෙවරක් පන්දුව ස්පර්ශ කිරීම තහනම්ය (ආවරණ ස්පර්ශයකින් පසුව හැර)."),
        q("වොලිබෝල් ක්‍රීඩාවේ වෙනස් පාට ජර්සියක් ඇඳ ක්‍රීඩා කරන ආරක්ෂක විශේෂඥ ක්‍රීඩකයා හඳුන්වන්නේ කෙසේද?", "ලිබරෝ ක්‍රීඩකයා (Libero)", "නායකයා", "පන්දු සකසන්නා", "ප්‍රහාරකයා", "ලිබරෝ පසුපස කලාපයේ පන්දු රැකීමට පමණක් සීමා වූ විශිෂ්ට ආරක්ෂක ක්‍රීඩකයෙකි."),
        q("වොලිබෝල් ක්‍රීඩාවේ ලිබරෝ ක්‍රීඩකයාට (Libero) නීතියෙන් තහනම් කර ඇති ක්‍රියාකාරකම් මොනවාද?", "පන්දු පිරිනැමීම (Serve), ප්‍රහාරක පහර ගැසීම සහ ආවරණය කිරීම (Block)", "පන්දු රැකීම", "යටි අත් පහර දීම", "පිටියට ඇතුළු වීම", "ලිබරෝට දැලට ඉහළින් පන්දුවට ප්‍රහාරක පහර එල්ල කිරීම හෝ පිරිනැමීම කළ නොහැක."),
        q("වොලිබෝල් තරගයක වටයක් (Set) ජයග්‍රහණය කිරීම සඳහා ලබාගත යුතු අවම ලකුණු සංඛ්‍යාව සහ ලකුණු පරතරය කුමක්ද?", "අවම වශයෙන් ලකුණු 2ක පරතරයක් සහිතව ලකුණු 25ක්", "ලකුණු 21ක්", "ලකුණු 15ක්", "ලකුණු 30ක්", "මුල් වට 4 ලකුණු 25ට පවත්වන අතර ලකුණු 24-24 වූ විට ලකුණු 2ක පරතරයක් ලැබෙන තෙක් තරගය දිගටම පැවැත්වේ."),
        q("වොලිබෝල් තරගයක 5 වන තීරණාත්මක වටය (Deciding Set) පවත්වනු ලබන්නේ ලකුණු කීයකටද?", "ලකුණු 2ක පරතරයක් සහිතව ලකුණු 15කට", "ලකුණු 25කට", "ලකුණු 21කට", "ලකුණු 10කට", "වට 2-2ක් ලෙස සම වූ විට අවසන් තීරණාත්මක 5 වන වටය ලකුණු 15කට පවත්වයි."),
        q("දැල්පන්දු (Netball) ක්‍රීඩා පිටියක සම්මත නිල දිග සහ පළල පිළිවෙළින් කොපමණද?", "දිග මීටර් 30.5ක් සහ පළල මීටර් 15.25ක් (අඩි 100 × 50)", "දිග මීටර් 20ක් සහ පළල මීටර් 10ක්", "දිග මීටර් 40ක් සහ පළල මීටර් 20ක්", "දිග මීටර් 18ක් සහ පළල මීටර් 9ක්", "දැල්පන්දු පිටිය දිගින් සමාන තෙවැනි කලාප 3කට (Thirds) බෙදා ඇත."),
        q("දැල්පන්දු ක්‍රීඩාවේ දැල් කණුවේ (Goal Post) සම්මත උස ප්‍රමාණය මීටර් කීයද?", "මීටර් 3.05කි (අඩි 10)", "මීටර් 2.43කි", "මීටර් 3.50කි", "මීටර් 2.80කි", "දැල් කණුවේ උස මීටර් 3.05ක් වන අතර මුදුනේ ඇති වළල්ලේ විෂ්කම්භය මිලිමීටර 380කි."),
        q("දැල්පන්දු පිටියේ ගෝල වෘත්තයේ (Goal Circle) අරය මීටර් කීයක්ද?", "මීටර් 4.9කි (අඩි 16)", "මීටර් 3.0කි", "මීටර් 6.0කි", "මීටර් 2.5කි", "ගෝල කණුව කේන්ද්‍ර කරගත් මීටර් 4.9ක අර්ධ වෘත්තාකාර කලාපය ගෝල වෘත්තයයි."),
        q("දැල්පන්දු තරගයකදී එක් කණ්ඩායමකින් පිටියේ ක්‍රීඩා කරන ක්‍රීඩිකාවන් සංඛ්‍යාව කීයද?", "ක්‍රීඩිකාවන් 7කි", "ක්‍රීඩිකාවන් 6කි", "ක්‍රීඩිකාවන් 5කි", "ක්‍රීඩිකාවන් 11කි", "එක් පිලකට නියමිත පිහිටීම් (Positions) සහිත ක්‍රීඩිකාවන් 7 දෙනෙකු සහභාගී වේ."),
        q("දැල්පන්දු ක්‍රීඩාවේ ගෝල ලබාගැනීමේ අවසරය ඇති එකම ක්‍රීඩිකාවන් දෙදෙනා කවුද?", "ගෝල් ෂූටර් (GS) සහ ගෝල් ඇටෑක් (GA)", "සෙන්ටර් (C) සහ වින්ග් ඇටෑක් (WA)", "ගෝල් ඩිෆෙන්ස් (GD) සහ ගෝල් කීපර් (GK)", "වින්ග් ඩිෆෙන්ස් (WD) සහ GS", "GS සහ GA හට පමණක් ගෝල වෘත්තය තුළ සිට දැල තුළට පන්දුව යොමු කර ලකුණු ලබාගත හැක."),
        q("දැල්පන්දු පිටියේ ගෝල වෘත්තය හැර පිටියේ අනෙක් සියලුම ප්‍රදේශවල (Thirds 3හිම) ක්‍රීඩා කළ හැකි ක්‍රීඩිකාව කවුද?", "සෙන්ටර් හෙවත් මධ්‍ය ක්‍රීඩිකාව (C)", "වින්ග් ඇටෑක් (WA)", "ගෝල් ඇටෑක් (GA)", "ගෝල් කීපර් (GK)", "සෙන්ටර් ක්‍රීඩිකාවට දෙපස ගෝල වෘත්ත දෙක හැර මුළු පිටිය පුරාම ගමන් කළ හැක."),
        q("දැල්පන්දු ක්‍රීඩාවේ 'තත්පර 3 නීතිය' (Held Ball) යන්නෙන් අදහස් කරන්නේ කුමක්ද?", "පන්දුව අතැති ක්‍රීඩිකාවකට තත්පර 3කට වඩා වැඩි කාලයක් පන්දුව තබාගත නොහැකි වීම", "තත්පර 3ක් ඇතුළත ගෝලයක් ලබාගත යුතු වීම", "තත්පර 3ක් දුවන්නට සිදුවීම", "තත්පර 3ක් නිශ්චලව සිටීම", "පන්දුව අතට ගත් මොහොතේ සිට තත්පර 3ක් ඇතුළත එය වෙනත් අයෙකුට පාස් කළ යුතුය හෝ ෂූට් කළ යුතුය."),
        q("දැල්පන්දු ක්‍රීඩාවේ 'බාධා කිරීමේ නීතිය' (Obstruction Rule) අනුව ආරක්ෂක ක්‍රීඩිකාව පන්දුව සහිත ක්‍රීඩිකාවගෙන් තැබිය යුතු අවම පරතරය කොපමණද?", "මීටර් 0.9කි (අඩි 3ක්)", "මීටර් 2.0කි", "මීටර් 0.5කි", "මීටර් 1.5කි", "පන්දුව සහිත ක්‍රීඩිකාවගේ බිම තැබූ ඉදිරි පාදයේ සිට මීටර් 0.9ක දුරක් නොතබා දෑත් විහිදුවා බාධා කිරීම දඬුවම් ලැබිය හැකි වරදකි."),
        q("දැල්පන්දු ක්‍රීඩිකාවකට තමන්ට හිමි නොවන සීමා කලාපයකට ඇතුළු වීම නිසා ලැබෙන දඬුවම් වරද කුමක්ද?", "සීමා ඉක්මවා යාම හෙවත් ඕෆ්සයිඩ් (Offside)", "බාධා කිරීම", "පෞද්ගලික ගැටීම", "තත්පර 3 වරද", "තමන්ගේ භූමිකාවට අදාළ කලාපයෙන් පිටතට පාදය තැබීම ඕෆ්සයිඩ් වරදක් වන අතර විරුද්ධ පිලට නිදහස් පාස් පහරක් ලැබේ."),
        q("දැල්පන්දු තරගයක නිල කාලසීමාව මිනිත්තු කීයක කාර්තු (Quarters) කීයකින් සමන්විත වේද?", "මිනිත්තු 15 බැගින් වූ කාර්තු 4ක් (මුළු මිනිත්තු 60)", "මිනිත්තු 20 බැගින් අර්ධ 2ක්", "මිනිත්තු 10 බැගින් කාර්තු 4ක්", "මිනිත්තු 45 අර්ධ 2ක්", "සම්මත ජාත්‍යන්තර දැල්පන්දු තරගයක් මිනිත්තු 15ක කාර්තු 4කින් සමන්විත වේ."),
        q("පාපන්දු (Football) ක්‍රීඩා පිටියක ගෝල කණුවේ සම්මත පළල සහ උස පිළිවෙළින් කොපමණද?", "පළල මීටර් 7.32ක් (යාර 8) සහ උස මීටර් 2.44ක් (අඩි 8)", "පළල මීටර් 5ක් සහ උස මීටර් 2ක්", "පළල මීටර් 9ක් සහ උස මීටර් 3ක්", "පළල මීටර් 6ක් සහ උස මීටර් 2.2ක්", "FIFA සම්මත ගෝල කණුවේ පළල යාර 8ක් හා උස අඩි 8කි."),
        q("පාපන්දු තරගයකදී එක් කණ්ඩායමකින් පිටියේ ක්‍රීඩා කරන සම්පූර්ණ ක්‍රීඩකයන් සංඛ්‍යාව කීයද?", "ක්‍රීඩකයන් 11කි (ගෝල රකින්නා ඇතුළුව)", "ක්‍රීඩකයන් 9කි", "ක්‍රීඩකයන් 12කි", "ක්‍රීඩකයන් 7කි", "එක් පිලකට ගෝල රකින්නා සමග ක්‍රීඩකයන් 11 දෙනෙකු සහභාගී වේ."),
        q("පාපන්දු තරගයක සම්මත නිල කාලසීමාව මිනිත්තු කීයක්ද?", "මිනිත්තු 45 බැගින් වූ අර්ධ 2ක් (මුළු මිනිත්තු 90)", "මිනිත්තු 30 බැගින් අර්ධ 2ක්", "මිනිත්තු 60ක්", "මිනිත්තු 20 බැගින් කාර්තු 4ක්", "අර්ධ දෙක අතර මිනිත්තු 15ක විවේක කාලයක් සහිතව මිනිත්තු 90ක් ක්‍රීඩා කෙරේ."),
        q("පාපන්දු ක්‍රීඩාවේ 'ඕෆ්සයිඩ් නීතිය' (Offside Rule) ක්‍රියාත්මක වන්නේ කුමන අවස්ථාවකදීද?", "පන්දුව පාස් කරන මොහොතේ ප්‍රහාරකයා ප්‍රතිවාදී අර්ධයේ පන්දුවට සහ දෙවන අවසාන ප්‍රතිවාදියාට වඩා ඉදිරියෙන් සිටින විට", "තමන්ගේම අර්ධයේ සිටින විට", "කෝනර් පහරකදී", "ත්‍රෝ-ඉන් පහරකදී", "පන්දුව යොමු කරන මොහොතේ ප්‍රතිවාදී ගෝල රකින්නා හැර අනෙක් අවසන් ආරක්ෂකයාට වඩා ඉදිරියෙන් සිටීම ඕෆ්සයිඩ් වේ."),
        q("පාපන්දු ක්‍රීඩාවේදී ඕෆ්සයිඩ් (Offside) නීතිය බලනොපාන අවස්ථාවකට නිදසුනක් කුමක්ද?", "ත්‍රෝ-ඉන් (Throw-in), කොනක පහර (Corner kick) හෝ ගෝල පහර (Goal kick) මගින් කෙළින්ම පන්දුව ලැබෙන විට", "සාමාන්‍ය පාස් එකකදී", "නිදහස් පහරකදී", "ප්‍රහාරක කලාපයේදී", "මෙම විශේෂ අවස්ථා තුනේදී ඍජුවම පන්දුව ලැබෙන ක්‍රීඩකයෙකු ඕෆ්සයිඩ් නොවේ."),
        q("පාපන්දු ක්‍රීඩාවේදී දඬුවම් පහරක් (Penalty Kick) ලබාදෙන්නේ කුමන වරදක් සඳහාද?", "ආරක්ෂක ක්‍රීඩකයෙකු තම දඬුවම් සීමාව (Penalty Area) තුළදී සෘජු නිදහස් පහරකට හිමි බරපතළ වරදක් කළ විට", "පිටිය මැදදී ෆවුල් කළ විට", "ඕෆ්සයිඩ් වූ විට", "කෝනර් එකක් ගැසූ විට", "දඬුවම් සීමාව තුළ සිදුවන බරපතළ වැරදි සඳහා මීටර් 11 ලක්ෂ්‍යයේ සිට පෙනල්ටි පහර පිරිනැමේ."),
        q("පාපන්දු ක්‍රීඩාවේදී පන්දුව පිටියේ පැති ඉරෙන් (Touchline) පිටතට ගිය විට ක්‍රීඩාව නැවත ආරම්භ කරන්නේ කෙසේද?", "දෑතින්ම හිසට ඉහළින් පන්දුව විසි කිරීමෙන් (Throw-in)", "පයින් ගැසීමෙන්", "ගෝල පහරකින්", "විනිසුරු පන්දුව අතහැරීමෙන්", "ත්‍රෝ-ඉන් කිරීමේදී ක්‍රීඩකයාගේ දෙපා බිම ස්පර්ශව තිබිය යුතු අතර හිසට පිටුපසින් දෑතින්ම විසි කළ යුතුය."),
        q("පාපන්දු විනිසුරුවරයෙකු විසින් ක්‍රීඩකයෙකුට 'කහ කාඩ්පතක්' (Yellow Card) පෙන්වන්නේ කුමන හේතුවක් නිසාද?", "නොමනා හැසිරීම් හෝ නීති විරෝධී ක්‍රීඩා විලාශය පිළිබඳ නිල වශයෙන් අවවාද කිරීම සඳහා", "තරගයෙන් නෙරපා හැරීමට", "ගෝලයක් ලබාදුන් විට", "විවේකය ලබාදීමට", "එක් තරගයකදී කහ කාඩ්පත් 2ක් ලැබූ ක්‍රීඩකයෙකුට රතු කාඩ්පතක් පෙන්වා පිටියෙන් ඉවත් කරනු ලැබේ."),
        q("පාපන්දු ක්‍රීඩකයෙකුට විනිසුරු විසින් 'රතු කාඩ්පතක්' (Red Card) පෙන්වූ විට සිදුවන නීතිමය ක්‍රියාමාර්ගය කුමක්ද?", "ක්‍රීඩකයා වහාම පිටියෙන් ඉවත් විය යුතු අතර ආදේශක ක්‍රීඩකයෙකු යෙදවිය නොහැක (ක්‍රීඩකයන් 10 දෙනෙකු බවට පත්වේ)", "විනාඩි 10කට පිටියෙන් යාම", "වෙනත් ක්‍රීඩකයෙකු දැමීම", "ලකුණු අඩු කිරීම", "රතු කාඩ්පතක් ලැබූ ක්‍රීඩකයාට එම තරගය මෙන්ම ඊළඟ තරගයද අහිමි වේ."),
        q("ශ්‍රී ලංකාවේ සාම්ප්‍රදායික දේශීය ක්‍රීඩාවක් වන 'එල්ලේ' (Elle) ක්‍රීඩාවේ එක් කණ්ඩායමක නිල ක්‍රීඩකයන් සංඛ්‍යාව කීයද?", "ක්‍රීඩකයන් 16කි (පිටියේ 14ක් හෝ 12ක් ක්‍රීඩා කරයි)", "ක්‍රීඩකයන් 11කි", "ක්‍රීඩකයන් 9කි", "ක්‍රීඩකයන් 6කි", "එල්ලේ ක්‍රීඩාවේ පන්දු රකින්නන් 14 දෙනෙකු හෝ 12 දෙනෙකු පිටියේ ස්ථානගත වේ."),
        q("එල්ලේ ක්‍රීඩාවේදී පිතිකරුවා පන්දුවට පහර දීම සඳහා භාවිත කරන පිත්ත සාදා ඇත්තේ කුමන ද්‍රව්‍යයකින්ද?", "හොඳින් පදම් කළ උණ ලීයෙන් (Bamboo)", "තේක්ක ලීයෙන්", "ප්ලාස්ටික් වලින්", "යකඩ වලින්", "උණ ලීයේ ඇති නම්‍යශීලී බව සහ ශක්තිය නිසා එල්ලේ පිත්ත සඳහා උණ ලී සම්මත වේ."),
        q("එල්ලේ ක්‍රීඩාවේදී ධාවකයෙකු ලකුණක් සම්පූර්ණ කිරීම සඳහා පිළිවෙළින් තරණය කළ යුතු ඉනිම් (Bases) මොනවාද?", "1 වන ඉනිම — 2 වන ඉනිම — 3 වන ඉනිම — නිවාසය (Home)", "1 වන ඉනිම — නිවාසය", "2 වන ඉනිම — 1 වන ඉනිම", "කැමති ඉනිමක්", "ක්‍රීඩකයා ඉනිම 1, 2, 3 පිළිවෙළින් ස්පර්ශ කර නිවාසයට පැමිණි විට එක් ලකුණක් (Run) හිමි වේ."),
        q("එල්ලේ ක්‍රීඩාවේදී ධාවකයෙකු 'දැවී යාමක්' (Out) සිදුවන ප්‍රධාන අවස්ථාවක් නොවන්නේ කුමක්ද?", "ඉනිමක සීමා තුළ පය තබාගෙන සිටින විට පන්දුවෙන් ශරීරයේ ගැටීම", "ඉනිමෙන් ඉවතට දිව යන විට පන්දුවෙන් ගසා ටැග් කිරීම", "පහරදුන් පන්දුව බිම නොවැටී උඩපන්දුවක් ලෙස රැකගැනීම", "නියමිත වට ප්‍රමාණය ඉක්මවා යාම", "ක්‍රීඩකයා ඉනිම මත ආරක්ෂිතව සිටින විට පන්දුවෙන් ගැසුවද දැවී යාමක් සිදු නොවේ."),
        q("ඔලිම්පික් සම්මත පිහිනුම් තටාකයක (Olympic Swimming Pool) නිල දිග, පළල සහ අවම ගැඹුර කොපමණද?", "දිග මීටර් 50ක්, පළල මීටර් 25ක් සහ අවම ගැඹුර මීටර් 2ක්", "දිග මීටර් 25ක්, පළල මීටර් 12ක්", "දිග මීටර් 100ක්, පළල මීටර් 50ක්", "දිග මීටර් 30ක්, පළල මීටර් 15ක්", "ඔලිම්පික් පිහිනුම් තටාකය මීටර් 2.5 බැගින් වූ මංතීරු 10කින් හෝ 8කින් සමන්විත වේ."),
        q("පිහිනුම් ක්‍රීඩාවේ ඇති නිල පිහිනුම් ආර 4 අතරින් වඩාත්ම වේගවත්ම පිහිනුම් ආර කුමක්ද?", "නිදහස් ආර හෙවත් ඉදිරි බඩගෑම (Freestyle / Front Crawl)", "පසුපස ආර", "ළය ආර", "සමනල ආර", "ඉදිරි බඩගෑම (Front Crawl) ජලයේ අවම ප්‍රතිරෝධයක් සහිත වේගවත්ම පිහිනුම් ආරයි."),
        q("පිහිනුම් ආර 4 අතුරින් ආරම්භක පිම්ම (Dive) නොමැතිව ජලය තුළ සිටම තරගය ආරම්භ කරන එකම ආර කුමක්ද?", "පසුපස ආර (Backstroke)", "නිදහස් ආර", "ළය ආර", "සමනල ආර", "පසුපස ආර පිහිනුම්කරුවන් තටාකයේ බිත්තිය අල්ලාගෙන ජලය තුළ සිට තරගය අරඹයි."),
        q("සමනල ආර (Butterfly Stroke) පිහිනීමේදී පාදවලින් සිදුකරන විශේෂිත චලනය හඳුන්වන්නේ කෙසේද?", "ඩොල්ෆින් පා පහර (Dolphin Kick)", "කතුරු පා පහර", "ගෙඹි පා පහර", "පැද්දුම් පා පහර", "සමනල ආරේදී දෙපා එකට තබා ඩොල්ෆින් මත්ස්‍යයෙකු මෙන් ඉහළ පහළ තරංගාකාරව පා පහර එල්ල කරයි."),
        q("ගෙම්බෙකු පිහිනන ආකාරයට සමාන වන පැරණිතම හා සෙමින්ම පිහිනන සම්මත ආර කුමක්ද?", "ළය ආර (Breaststroke)", "නිදහස් ආර", "පසුපස ආර", "සමනල ආර", "ළය ආරේදී දෑත් සහ පාද ජලය යටින් සමමිතිකව චලනය කරමින් ගෙඹි පා පහරක් එල්ල කරයි."),
        q("තනි පුද්ගල මිශ්‍ර පිහිනුම් (Individual Medley - IM) ඉසව්වේ පිහිනුම් ආර 4 පෙළගස්වා ඇති නිවැරදි අනුපිළිවෙළ කුමක්ද?", "සමනල ආර — පසුපස ආර — ළය ආර — නිදහස් ආර (Fly, Back, Breast, Free)", "නිදහස් — ළය — පසුපස — සමනල", "පසුපස — ළය — සමනල — නිදහස්", "ළය — සමනල — නිදහස් — පසුපස", "තනි පුද්ගල මිශ්‍ර ඉසව්ව සමනල ආරෙන් ආරම්භ වී නිදහස් ආරෙන් නිමාවට පත්වේ."),
        q("සහය පිහිනුම් මිශ්‍ර ඉසව්වේ (Medley Relay) පළමු පිහිනුම්කරු පිහිනිය යුතු අනිවාර්ය ආර කුමක්ද?", "පසුපස ආර (Backstroke)", "සමනල ආර", "ළය ආර", "නිදහස් ආර", "පසුපස ආර ජලය තුළින් ආරම්භ කළ යුතු බැවින් සහය මිශ්‍ර ඉසව්වේ මුලින්ම පිහිනන්නේ පසුපස ආරයි."),
        q("ජලයේ ගිලෙන පුද්ගලයෙකු බේරාගැනීමේදී ගලවාගන්නාගේ ජීවිත ආරක්ෂාව තහවුරු කරන ප්‍රමුඛතා අනුපිළිවෙළ කුමක්ද?", "ළඟා වීම (Reach) — විසිකිරීම (Throw) — පැද යාම (Row) — පිහිනා යාම (Go/Tow)", "වහාම ජලයට පැනීම — පිහිනීම", "කෑගැසීම — ගල් ගැසීම", "බලා සිටීම පමණි", "ජලයට නොබැස ගොඩබිම සිට ලීයක් හෝ කඹයක් දිගු කිරීම වඩාත්ම ආරක්ෂිත මූලික පියවරයි."),
        q("ක්‍රීඩා තරගාවලියක් සංවිධානය කිරීමේදී 'ලීග් ක්‍රමය' (League Tournament) යන්නෙහි නිවැරදි අර්ථය කුමක්ද?", "තරගාවලියට සහභාගී වන සෑම කණ්ඩායමක්ම අනෙක් සියලුම කණ්ඩායම් සමග තරග වැදීම", "පැරදුණු සැනින් ඉවත් වීම", "එක් තරගයක් පමණක් පැවැත්වීම", "අවසාන තරගය පමණක් පැවැත්වීම", "ලීග් ක්‍රමයේදී එක් එක් කණ්ඩායමේ සැබෑ දක්ෂතාව සාධාරණව මැනිය හැකි අතර වැඩිම ලකුණු ලබන පිල ශූරතාව දිනයි."),
        q("කණ්ඩායම් N සංඛ්‍යාවක් සහභාගී වන තනි ලීග් තරගාවලියක (Single League) පැවැත්විය යුතු මුළු තරග සංඛ්‍යාව ගණනය කරන සූත්‍රය කුමක්ද?", "N(N — 1) / 2", "N — 1", "2N", "N²", "කණ්ඩායම් 6ක් සිටී නම් මුළු තරග ගණන 6(6 - 1) / 2 = 15කි."),
        q("පිළිමළුන් පිටුදැකීමේ ක්‍රමයේ (Knockout Tournament) ප්‍රධානතම ලක්ෂණය කුමක්ද?", "එක් තරගයකින් පරාජය වන කණ්ඩායම වහාම තරගාවලියෙන් ඉවත් වීම", "සෑම කණ්ඩායමක්ම තරග 5ක් ක්‍රීඩා කිරීම", "පරාජය වුවද දිගටම ක්‍රීඩා කිරීම", "ලකුණු එකතු කිරීම", "නොක්අවුට් ක්‍රමයේදී අඩු කාලයකින් හා අඩු වියදමකින් ශූරයා තෝරාගත හැක."),
        q("කණ්ඩායම් N සංඛ්‍යාවක් සහභාගී වන පිළිමළුන් පිටුදැකීමේ (Knockout) තරගාවලියක මුළු තරග සංඛ්‍යාව ගණනය කරන්නේ කෙසේද?", "N — 1", "N(N — 1) / 2", "N + 1", "2N — 1", "කණ්ඩායම් 16ක් සහභාගී වන්නේ නම් ශූරයා තේරීමට තරග 15ක් (16 - 1 = 15) පැවැත්විය යුතුය."),
        q("පිළිමළුන් පිටුදැකීමේ තරගාවලියක කණ්ඩායම් සංඛ්‍යාව 2හි බලයක් (2, 4, 8, 16, 32) නොවන විට පළමු වටයේදී තරග නොකර දෙවන වටයට සුදුසුකම් ලැබීම හඳුන්වන්නේ කෙසේද?", "බයි (Bye) ලබාදීම", "වෝක්-ඕවර් එකක්", "ලීග් ප්‍රසාදය", "දඬුවමක්", "ඊළඟ ඉහළම 2හි බලයෙන් කණ්ඩායම් ගණන අඩු කිරීමෙන් ලැබෙන අගයට බයි (Byes = 2^n - N) හිමි වේ."),
        q("කණ්ඩායම් 11ක් සහභාගී වන පිළිමළුන් පිටුදැකීමේ (Knockout) තරගාවලියකදී ලබාදිය යුතු 'බයි' (Byes) සංඛ්‍යාව කීයද?", "බයි 5කි (16 — 11 = 5)", "බයි 3කි", "බයි 2කි", "බයි 6කි", "11ට ආසන්න ඊළඟ 2හි බලය 16 වන බැවින් 16 - 11 = 5ක් බයි ලෙස දෙවන වටයට යොමු කෙරේ."),
        q("කණ්ඩායම් 11ක් සහභාගී වන නොක්අවුට් තරගාවලියක පළමු වටයේදී (First Round) පැවැත්වෙන මුළු තරග සංඛ්‍යාව කීයද?", "තරග 3කි", "තරග 5කි", "තරග 6කි", "තරග 4කි", "කණ්ඩායම් 11න් 5කට බයි හිමි වූ පසු ඉතිරි කණ්ඩායම් 6 අතර පළමු වටයේ තරග 3ක් (6/2 = 3) පැවැත්වේ."),
        q("තරගාවලියක පෙර වසරේ දක්ෂතා දැක්වූ ප්‍රබල කණ්ඩායම් මුල් වටවලදීම එකිනෙකා හමුවී ඉවත් වීම වැළැක්වීමේ ක්‍රමවේදය කුමක්ද?", "ශ්‍රේණිගත කිරීම හෙවත් සීඩිං ක්‍රමය (Seeding)", "බයි ලබාදීම පමණක්", "ලීග් ක්‍රමය", "කුසපත් ඇදීම", "පෙර වසරේ ශූරයන් හා අනුශූරයන් වරහනේ ඉහළ හා පහළ දෙකෙළවර ස්ථානගත කර අවසන් තරගය තෙක් හමු නොවන සේ සැලසුම් කරයි."),
        q("ක්‍රිකට් (Cricket) ක්‍රීඩාවේ පිච් එකක (Pitch) කඩුලු දෙක අතර සම්මත නිල දුර ප්‍රමාණය කොපමණද?", "යාර 22කි (මීටර් 20.12කි)", "යාර 20කි", "යාර 25කි", "මීටර් 15කි", "ක්‍රිකට් පිච් එකේ කඩුලු දෙක අතර දිග යාර 22ක් හෙවත් අඟල් 66කි."),
        q("ක්‍රිකට් ක්‍රීඩාවේ පිතිකරුවා පන්දුවට පහර දෙන සීමාව ලකුණු කරන ඉදිරිපස රේඛාව හඳුන්වන්නේ කෙසේද?", "පොපිං ක්‍රීස් රේඛාව (Popping Crease)", "බෝලිං ක්‍රීස්", "රිටර්න් ක්‍රීස්", "මායිම් රේඛාව", "කඩුල්ලේ සිට අඩි 4ක් ඉදිරියෙන් පොපිං ක්‍රීස් රේඛාව ඇඳ ඇති අතර පිතිකරුවා දැවී යාමෙන් ආරක්ෂා වන සීමාවයි."),
        q("ක්‍රිකට් නීති අනුව පන්දුව පිත්තේ නොගැටී පිතිකරුවාගේ පා ආවරණයේ (Pads) ගැටී කඩුල්ලේ වදින බව විනිසුරු තීරණය කළ විට දෙන දැවී යාම කුමක්ද?", "කඩුල්ල මුවා කිරීමේ වරද (LBW — Leg Before Wicket)", "කඩුල්ල බිඳහෙළීම", "ස්ටම්ප් කිරීම", "දුවද්දී දැවී යාම", "පිතිකරුවාගේ ශරීරය කඩුල්ලට එල්ල වන පන්දුවට බාධා කළ විට LBW දැවී යාමක් ලෙස තීරණය වේ."),
        q("ක්‍රිකට් පිතිකරුවෙකු පන්දුවට පහර දීමට ක්‍රීස් සීමාවෙන් ඉදිරියට ගිය විට පන්දුව කෙළින්ම අල්ලා කඩුලු රකින්නා විසින් කඩුල්ල බිඳ දැමීම හඳුන්වන්නේ කෙසේද?", "ස්ටම්ප් කිරීම (Stumped)", "දුවද්දී දැවී යාම (Run out)", "පන්දුව කෙළින්ම කඩුල්ලේ වැදීම", "හිට් විකට්", "ස්ටම්ප් කිරීම සිදුවන්නේ පන්දු රකින්නා නොව කඩුලු රකින්නා විසින්ම පන්දුව අල්ලා කඩුල්ල බිඳ දැමූ විටය."),
        q("පිතිකරුවෙකු පන්දුවට පහර දෙන අතරතුර හෝ ධාවනය අරඹන විට තම පිත්ත හෝ ශරීරය කඩුල්ලේ ගැටී බේල්ස් බිම වැටුණහොත් දෙන දැවී යාම කුමක්ද?", "හිට් විකට් (Hit Wicket)", "ස්ටම්ප් කිරීම", "දුවද්දී දැවී යාම", "LBW", "පිතිකරුවාගේම පහරකින් හෝ ඇඳුමකින් බේල්ස් ඉවත් වීම හිට් විකට් දැවී යාමකි."),
        q("ක්‍රිකට් තරගයක විනිසුරුවන්ගේ තීරණ නැවත පරීක්ෂා කිරීම සඳහා පිතිකරුවන්ට සහ පන්දු රකින නායකයාට ඇති තාක්ෂණික අවස්ථාව කුමක්ද?", "තීරණ සමාලෝචන පද්ධතිය (DRS — Decision Review System)", "විනිසුරු සාකච්ඡාව", "කණ්ඩායම් රැස්වීම", "ලකුණු පුවරු පරීක්ෂාව", "Hawk-Eye, UltraEdge සහ Ball Tracking තාක්ෂණය යොදාගනිමින් තෙවන විනිසුරු මගින් තීරණය සමාලෝචනය කරයි."),
        q("බැඩ්මින්ටන් (Badminton) තනි ක්‍රීඩක (Singles) පිටියක සම්මත දිග සහ පළල පිළිවෙළින් කොපමණද?", "දිග මීටර් 13.40ක් සහ පළල මීටර් 5.18ක්", "දිග මීටර් 15.00ක් සහ පළල මීටර් 6.00ක්", "දිග මීටර් 10.00ක් සහ පළල මීටර් 4.00ක්", "දිග මීටර් 18.00ක් සහ පළල මීටර් 9.00ක්", "තනි ඉසව්වේදී පැති අතිරේක තීරුව (Side alley) පිටත සීමාවක් ලෙස සැලකේ."),
        q("බැඩ්මින්ටන් යුගල (Doubles) පිටියක සම්මත දිග සහ පළල පිළිවෙළින් කොපමණද?", "දිග මීටර් 13.40ක් සහ පළල මීටර් 6.10ක්", "දිග මීටර් 14.00ක් සහ පළල මීටර් 7.00ක්", "දිග මීටර් 12.00ක් සහ පළල මීටර් 5.00ක්", "දිග මීටර් 16.00ක් සහ පළල මීටර් 8.00ක්", "යුගල තරග සඳහා සම්පූර්ණ පිටියේ පළල වන මීටර් 6.10ම භාවිත වේ."),
        q("බැඩ්මින්ටන් දැලෙහි උස කණු අසලදී සහ මධ්‍යයේදී පිළිවෙළින් කොපමණද?", "කණු අසලදී මීටර් 1.55ක් සහ මධ්‍යයේදී මීටර් 1.524ක්", "කණු අසලදී මීටර් 2.00ක් සහ මැද මීටර් 1.80ක්", "සෑම තැනකම මීටර් 1.00ක්", "කණු අසලදී මීටර් 1.20ක්", "දැලෙහි බර නිසා මැදින් මඳක් පහත් වන අතර මැද උස මීටර් 1.524ක් (අඩි 5ක්) විය යුතුය."),
        q("බැඩ්මින්ටන් තරගයක වටයක් (Game) ජයග්‍රහණය කිරීම සඳහා ලබාගත යුතු සම්මත ලකුණු සංඛ්‍යාව කීයද?", "ලකුණු 2ක පරතරයක් සහිතව ලකුණු 21ක්", "ලකුණු 15ක්", "ලකුණු 25ක්", "ලකුණු 11ක්", "වට 3න් 2ක් ජයගන්නා ක්‍රීඩකයා ජයග්‍රහණය කරන අතර එක් වටයක් ලකුණු 21කි."),
        q("බැඩ්මින්ටන් තරගයක ලකුණු 20-20ක් ලෙස සම වූ විට ජයග්‍රහණය තීරණය කරන්නේ කෙසේද?", "ලකුණු 2ක පැහැදිලි පරතරයක් ලබන තෙක් හෝ උපරිම ලකුණු 30ට මුලින්ම ළඟා වන තෙක්", "ඊළඟ ලකුණ ගත් සැනින්", "කාසියක් වාසි බැලීමෙන්", "තරගය අත්හිටුවීමෙන්", "ලකුණු 29-29 වූ විට 30 වන ලකුණ ගන්නා ක්‍රීඩකයා වහාම ජයග්‍රහණය කරයි (Golden Point)."),
        q("බැඩ්මින්ටන් ක්‍රීඩාවේ පන්දු පිරිනැමීම (Service) සිදුකළ යුතු නිවැරදි නීත්‍යානුකූල ආකාරය කුමක්ද?", "පිරිනමන්නාගේ ඉණ මට්ටමට පහළින් විකර්ණාකාරව විරුද්ධ කොටුවට පහර දීම", "හිසට ඉහළින් පහර දීම", "කෙළින්ම ඉදිරියට පහර දීම", "දැලට යටින් යැවීම", "පිරිනමන මොහොතේ පිහාටුව බිම සිට මීටර් 1.15ට වඩා පහළින් තිබිය යුතු අතර විකර්ණව සේවා කොටුව තුළට යා යුතුය."),
        q("මේසපන්දු (Table Tennis) ක්‍රීඩා මේසයක සම්මත දිග, පළල සහ උස පිළිවෙළින් කොපමණද?", "දිග මීටර් 2.74ක්, පළල මීටර් 1.525ක් සහ බිම සිට උස සෙන්ටිමීටර 76ක්", "දිග මීටර් 3ක්, පළල මීටර් 2ක්", "දිග මීටර් 2ක්, පළල මීටර් 1ක්", "දිග මීටර් 4ක්, පළල මීටර් 1.5ක්", "ITTF සම්මත මේසපන්දු මේසය තද කොළ, නිල් හෝ කළු පැහැති මැට් නිමාවකින් යුක්ත වේ."),
        q("මේසපන්දු දැලෙහි සම්මත උස ප්‍රමාණය කොපමණද?", "සෙන්ටිමීටර 15.25කි (අඟල් 6ක්)", "සෙන්ටිමීටර 30කි", "සෙන්ටිමීටර 10කි", "සෙන්ටිමීටර 25කි", "මේස මතුපිට සිට දැලෙහි උස සෙන්ටිමීටර 15.25ක් වේ."),
        q("මේසපන්දු තරගයකදී වටයක් (Set) ජයග්‍රහණය කිරීම සඳහා ලබාගත යුතු සම්මත ලකුණු සංඛ්‍යාව කීයද?", "ලකුණු 2ක පරතරයක් සහිතව ලකුණු 11ක්", "ලකුණු 21ක්", "ලකුණු 15ක්", "ලකුණු 25ක්", "නව නීති අනුව මේසපන්දු වටයක් ලකුණු 11කින් අවසන් වේ."),
        q("මේසපන්දු ක්‍රීඩාවේදී පන්දු පිරිනැමීමේ (Service) වාරය ක්‍රීඩකයන් අතර මාරු වන්නේ ලකුණු කීයකට වරක්ද?", "සෑම ලකුණු 2කට වරක් (ලකුණු 10-10 වූ විට සෑම ලකුණකට වරක්)", "සෑම ලකුණු 5කට වරක්", "සෑම ලකුණු 10කට වරක්", "වටය අවසන් වන තුරු මාරු නොවේ", "සාමාන්‍යයෙන් ලකුණු 2කට වරක් සර්විස් මාරු වන අතර ඩියුස් (10-10) වූ විට එක් ලකුණකට වරක් මාරු වේ."),
        q("මේසපන්දු ක්‍රීඩාවේ නීත්‍යානුකූල පන්දු පිරිනැමීමකදී පන්දුව අත්ලෙන් ඉහළට විසි කළ යුතු අවම උස කොපමණද?", "අවම වශයෙන් සෙන්ටිමීටර 16ක් (අඟල් 6ක්)", "සෙන්ටිමීටර 5ක්", "මීටර් 1ක්", "විසි නොකර අතින්ම පහර දිය හැක", "විවෘත සමතලා අත්ල මත තබා පන්දුව සිරස්ව අවම 16cm ක් ඉහළට විසි කර වැටෙන විට පහර දිය යුතුය."),
        q("පැසිපන්දු (Basketball) ක්‍රීඩා පිටියක සම්මත නිල දිග සහ පළල පිළිවෙළින් මීටර් කීයද?", "දිග මීටර් 28ක් සහ පළල මීටර් 15ක් (28m × 15m)", "දිග මීටර් 30ක් සහ පළල මීටර් 20ක්", "දිග මීටර් 25ක් සහ පළල මීටර් 12ක්", "දිග මීටර් 18ක් සහ පළල මීටර් 9ක්", "FIBA සම්මත පැසිපන්දු පිටියේ මාන මීටර් 28 × 15 වේ."),
        q("පැසිපන්දු වළල්ල (Ring) බිම මට්ටමේ සිට පිහිටා ඇති සම්මත උස ප්‍රමාණය කොපමණද?", "මීටර් 3.05කි (අඩි 10)", "මීටර් 2.43කි", "මීටර් 3.50කි", "මීටර් 2.80කි", "පැසිපන්දු වළල්ලේ උස අඩි 10ක් (3.05m) වන අතර වළල්ලේ විෂ්කම්භය මිලිමීටර 450කි."),
